import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.BJWn8LWy.js";const u=JSON.parse('{"title":"sphinx-vitepress","description":"","frontmatter":{"layout":"home","hero":{"name":"sphinx-vitepress","text":"Sphinx power, VitePress polish","tagline":"A Sphinx builder that renders your documentation with VitePress. Keep autodoc, docstrings and intersphinx, lose the dated theme.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Configuration","link":"/guide/configuration"},{"theme":"alt","text":"GitHub","link":"https://github.com/rohandahale/sphinx-vitepress"}]},"features":[{"title":"Keep your conf.py","details":"autodoc, napoleon, intersphinx and MyST are read-side extensions. Point sphinx-build at a new builder and your project is unchanged."},{"title":"Cross-references both ways","details":"intersphinx resolves outward as always, and your site publishes an objects.inv so other projects can link straight back into it."},{"title":"Versioned deploys","details":"One command builds stable/ and dev/ trees with a version picker and a root redirect, ready to push to GitHub Pages."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),s={name:"index.md"};function o(r,e,d,h,p,l){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sphinx-vitepress" tabindex="-1">sphinx-vitepress <a class="header-anchor" href="#sphinx-vitepress" aria-label="Permalink to &quot;sphinx-vitepress {#sphinx-vitepress}&quot;">​</a></h1><p><strong>sphinx-vitepress</strong> is a <a href="https://www.sphinx-doc.org" target="_blank" rel="noreferrer">Sphinx</a> builder that emits <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a>-flavored Markdown, a generated <code>.vitepress/config.mts</code>, and a theme, so an existing Sphinx project becomes a modern documentation site without giving up any of Sphinx’s machinery.</p><p>It is the Python counterpart of <a href="https://github.com/LuxDL/DocumenterVitepress.jl" target="_blank" rel="noreferrer">DocumenterVitepress.jl</a>:</p><blockquote><p><code>Sphinx : sphinx-vitepress :: Documenter.jl : DocumenterVitepress.jl</code></p></blockquote><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why {#why}&quot;">​</a></h2><p>Sphinx has the best extraction and cross-referencing in any language ecosystem: autodoc reads your code, napoleon understands NumPy and Google docstrings, and intersphinx links a type in your signature to the page that documents it in another project. What it has not had is a front end people enjoy reading.</p><p>VitePress supplies that: instant navigation, real search, dark mode. What it does not know is anything about Python. This builder is the join between them.</p><h2 id="what-you-keep" tabindex="-1">What you keep <a class="header-anchor" href="#what-you-keep" aria-label="Permalink to &quot;What you keep {#what-you-keep}&quot;">​</a></h2><p>Everything on the read side of Sphinx is untouched, because extensions like autodoc and MyST produce a document tree long before any builder runs:</p><ul><li><code>conf.py</code>, unchanged apart from optional <code>vitepress_*</code> settings</li><li>autodoc, autosummary, napoleon, MyST, and most third-party extensions</li><li>intersphinx in both directions, since your site publishes an <code>objects.inv</code></li><li>other Sphinx builders: <code>make latexpdf</code> still works from the same sources</li></ul>',10)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
